CREATE TABLE IF NOT EXISTS ph_users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 phone VARCHAR(12) NOT NULL UNIQUE, name VARCHAR(210) NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL,
 city VARCHAR(100) NOT NULL, district VARCHAR(100) NOT NULL, neighborhood VARCHAR(100) NOT NULL,
 password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'customer', dealer_status VARCHAR(20) NOT NULL DEFAULT 'pending',
 must_change_password TINYINT NOT NULL DEFAULT 0, password_expires BIGINT NULL,
 created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ph_sessions (token CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,expires BIGINT NOT NULL,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES ph_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ph_products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,data LONGTEXT NOT NULL,xml_key CHAR(64) NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ph_product_images (product_id BIGINT UNSIGNED NOT NULL,image_id CHAR(40) NOT NULL,PRIMARY KEY(product_id,image_id),INDEX image_lookup(image_id),FOREIGN KEY(product_id) REFERENCES ph_products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ph_uploads (id CHAR(40) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,mime VARCHAR(30) NOT NULL,data MEDIUMBLOB NOT NULL,FOREIGN KEY(user_id) REFERENCES ph_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ph_batches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,day DATE NOT NULL,UNIQUE(user_id,day),FOREIGN KEY(user_id) REFERENCES ph_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ph_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,batch_id BIGINT UNSIGNED NOT NULL,customer LONGTEXT NOT NULL,items LONGTEXT NOT NULL,total DECIMAL(12,2) NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'İncelemede',created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted_at DATETIME NULL,version INT NOT NULL DEFAULT 1,INDEX(batch_id),FOREIGN KEY(user_id) REFERENCES ph_users(id),FOREIGN KEY(batch_id) REFERENCES ph_batches(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ph_settings (`key` VARCHAR(100) PRIMARY KEY,value LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ph_notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type VARCHAR(10) NOT NULL,subject_id BIGINT UNSIGNED NOT NULL,created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,read_at DATETIME NULL,INDEX(type,subject_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ph_rates (id CHAR(64) PRIMARY KEY,window_start BIGINT NOT NULL,hits INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ph_xml_sources (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,url TEXT NOT NULL,mapping TEXT NOT NULL,commission DECIMAL(5,2) NOT NULL DEFAULT 20) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ph_xml_previews (token CHAR(48) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,expires BIGINT NOT NULL,data LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ph_xml_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,source_id BIGINT UNSIGNED NULL,created TIMESTAMP DEFAULT CURRENT_TIMESTAMP,count INT NOT NULL,status VARCHAR(20) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
